module fsm #(
    parameter s0 = 3'b000,
    parameter s1 = 3'b001,
    parameter s2 = 3'b010,
    parameter s3 = 3'b011,
    parameter s4 = 3'b100,
    parameter s5 = 3'b101
) (
    input IN,
    output reg MATCH,
    input CLK,
    input RST
);

parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;

reg [2:0] current_state, next_state;

always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = !IN ? S2 : S1;
        S2: next_state = !IN ? S3 : S1;
        S3: next_state = IN ? S4 : S0;
        S4: next_state = IN ? S5 : S0;
        S5: next_state = IN ? S1 : S0;
        default: next_state = S0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        current_state <= S0;
    end else begin
        current_state <= next_state;
    end
end

assign MATCH = (current_state == S5 && IN == 1);
endmodule
